__LL.af.push(function(LANGS){ Object.assign(LANGS.af.strings, {"Yesterday": "Gister", "unread": "ongelees", "All caught up": "Alles gelees", "New message": "Nuwe boodskap", "You": "Jy", "Send a message or instruction to your team.": "Stuur 'n boodskap of instruksie aan jou span.", "Messages from your employer will show here.": "Boodskappe van jou werkgewer verskyn hier.", "Reply to": "Antwoord aan", "Understood 👍": "Verstaan 👍", "Done ✅": "Klaar ✅", "On it": "Ek is daarmee besig", "I need help": "Ek het hulp nodig", "Type your reply": "Tik jou antwoord", "Waiting for replies": "Wag vir antwoorde", "New reply from": "Nuwe antwoord van", "Reply from": "Antwoord van"}); });
__LL.af.push(function(LANGS){ Object.assign(LANGS.af.strings, {"Messages now work like a chat: employees can reply to their employer, the employer can answer each employee, and everyone gets a tidy inbox with unread counts and quick replies": "Boodskappe werk nou soos 'n geselsie: werknemers kan hul werkgewer antwoord, die werkgewer kan elke werknemer antwoord, en almal kry 'n netjiese inbox met ongelese tellings en vinnige antwoorde"}); });
__LL.af.push(function(LANGS){ Object.assign(LANGS.af.strings, {"Delete this conversation?": "Skrap hierdie gesprek?", "It will be removed from your messages.": "Dit sal uit jou boodskappe verwyder word.", "You can also remove it for everyone.": "Jy kan dit ook vir almal verwyder.", "Delete for me": "Skrap vir my", "Delete for everyone": "Skrap vir almal", "Conversation deleted": "Gesprek geskrap", "Conversation deleted for everyone": "Gesprek vir almal geskrap"}); });
__LL.af.push(function(LANGS){ Object.assign(LANGS.af.strings, {"selected": "gekies", "Pick items from stock": "Kies items uit voorraad", "items added": "items bygevoeg", "more, search to narrow down": "meer, soek om te verklein", "Add selected": "Voeg geselekteerde by", "Tick boxes and Select all or Deselect all now appear wherever you pick stock: the sell page, the point of sale, invoices and purchase orders": "Merkblokkies en Kies alles of Ontkies alles verskyn nou oral waar jy voorraad kies: die verkoopblad, die verkooppunt, fakture en bestelorders"}); });
__LL.af.push(function(LANGS){ Object.assign(LANGS.af.strings, {"Delete selected?": "Skrap geselekteerde?", "They will be removed from your messages.": "Hulle sal uit jou boodskappe verwyder word.", "You can also remove them for everyone.": "Jy kan hulle ook vir almal verwyder.", "Deleted": "Geskrap", "Deleted for everyone": "Vir almal geskrap", "Select messages to delete": "Kies boodskappe om te skrap"}); });
__LL.af.push(function(LANGS){ Object.assign(LANGS.af.strings, {"Logo and templates": "Logo en sjablone", "Logo updated": "Logo opgedateer", "Logo removed": "Logo verwyder", "With your logo uploaded, your logo sits at the top left of every invoice, receipt and report and the Pesa mark at the top right, both the same size. Without a logo, the small Pesa mark is used at the top left.": "Met jou logo opgelaai verskyn jou logo bo links op elke faktuur, kwitansie en verslag en die Pesa-merk bo regs, albei ewe groot. Sonder logo word die klein Pesa-merk bo links gebruik.", "Your logo prints at the top left of documents and the Pesa mark at the top right, at the same size.": "Jou logo druk bo links op dokumente en die Pesa-merk bo regs, ewe groot.", "Letterhead removed from Settings. With a company logo uploaded, your logo prints at the top left of invoices, receipts and reports and the Pesa mark at the top right, both the same size": "Briefhoof is uit Instellings verwyder. Met 'n maatskappylogo opgelaai druk jou logo bo links op fakture, kwitansies en verslae en die Pesa-merk bo regs, albei ewe groot"}); });
